#!/bin/sh
umask 077
gun=${1:-$(date +%Y%m%d)}
in=/data/giden/stok_${gun}.txt
[ -f "$in" ] || { echo "girdi yok: $in" >&2; exit 3; }
n=$(wc -l < "$in"); t=$(awk -F, '{s+=$2} END {print s}' "$in")
echo "KALEM=$n TOPLAM=$t" > /data/arsiv/stok_kapanis_${gun}.txt
echo "kapanis dosyasi yazildi: KALEM=$n TOPLAM=$t"

#!/bin/sh
gun=$1
f=/data/arsiv/stok_kapanis_${gun}.txt
[ -r "$f" ] || { echo "kapanis dosyasi okunamadi: $f" >&2; exit 4; }
cat "$f"

-- mutabakat dosyasini mutabakat tablosuna yukler. Parametre: gun
\set dosya '/data/gelen/mutabakat_' :gun '.csv'
\set yukle '\\copy mutabakat_gecici from ' :'dosya' ' with (format csv, header true)'
:yukle
insert into mutabakat (hesap, tutar, gun) select hesap, tutar, :'gun' from mutabakat_gecici;
insert into yukleme_log (dosya, satir) select 'mutabakat_' || :'gun' || '.csv', count(*) from mutabakat_gecici;
truncate mutabakat_gecici;

-- asya stok dosyasini asya_stok tablosuna yukler. Parametre: gun
\set dosya '/data/gelen/tedarik/asya_' :gun '.csv'
\set yukle '\\copy asya_gecici from ' :'dosya' ' with (format csv, header true)'
:yukle
insert into asya_stok (urun, adet, gun) select urun, adet, :'gun' from asya_gecici;
truncate asya_gecici;

#!/bin/sh
# asya stok dosyasini denetler
f=/data/gelen/tedarik/asya_$1.csv
[ -f "$f" ] || { echo "dosya yok: $f" >&2; exit 4; }
n=$(($(wc -l < "$f") - 1))
[ "$n" -gt 0 ] || { echo "veri satiri yok" >&2; exit 5; }
echo "asya satir=$n"

-- hareket dosyasini hareket tablosuna yukler (anahtarsiz tablo). Parametre: gun
\set dosya '/data/gelen/hareket_' :gun '.csv'
\set yukle '\\copy hareket_gecici from ' :'dosya' ' with (format csv, header true)'
:yukle
insert into hareket (id, tarih, tutar) select id, tarih, tutar from hareket_gecici;
insert into yukleme_log (dosya, satir) select 'hareket_' || :'gun' || '.csv', count(*) from hareket_gecici;
truncate hareket_gecici;
